const FI=[{id:"p1",type:"review",user:US[0],time:"2h",bookRef:{title:"Intermezzo",author:"Sally Rooney",cc:"#3A5A4A"},title:"The architecture of longing",text:"Rooney builds Intermezzo like a fugue — two brothers, two registers, two ways of failing at intimacy. The formal innovation isn't the dual POV; it's how the prose style itself shifts between them.",rating:4,likes:47,comments:12,shelved:23,reposts:8,isLiked:false,isShelved:false,isReposted:false,tags:["literary-fiction","structure"],following:true,lensMatch:true},{id:"p2",type:"original",user:US[1],time:"4h",title:"Sixteen Funerals",text:"My grandmother attended sixteen funerals in the year she turned eighty. She told me once that grief has a sound — not the crying, not the hymns — but the moment after the last car leaves and the house goes quiet.\n\nI didn't understand until I heard it myself.",likes:89,comments:34,shelved:56,reposts:18,isLiked:true,isShelved:false,isReposted:false,tags:["flash-prose","grief"],following:true,isFirst:true,attestation:true},{id:"p3",type:"recommendation",user:US[4],time:"6h",bookRef:{title:"Orbital",author:"Samantha Harvey",cc:"#2A3A6A"},text:"If you've ever stared out a plane window and felt the weight of everyone below — read this. Harvey writes about astronauts the way mystics write about silence.",likes:112,comments:28,shelved:89,reposts:32,isLiked:false,isShelved:true,isReposted:false,tags:["literary-fiction"],following:true,lensMatch:true},{id:"p4",type:"spoiler",user:US[3],time:"8h",bookRef:{title:"James",author:"Percival Everett",cc:"#5A3A2A"},title:"The river scene rewrites everything",text:"When Jim's internal monologue drops the dialect for the first time — the real voice emerging — I physically set the book down.",spoilerPage:"p. 212",likes:34,comments:19,shelved:8,reposts:3,isLiked:false,isShelved:false,isReposted:false,tags:["historical-fiction"],lensMatch:true},{id:"p5",type:"original",user:US[7],time:"12h",title:"The Cartographer's Confession",text:"I have drawn borders where none exist. I have named rivers after men who never saw them. And in my seventy-third year, I understand that every map I made was a letter to someone I couldn't reach.\n\nMeasure it. Then forgive me for making it seem smaller than it was.",likes:203,comments:67,shelved:124,reposts:45,isLiked:false,isShelved:false,isReposted:false,tags:["poetry"],attestation:true,inspiredBy:{title:"Flights",author:"Olga Tokarczuk"}},{id:"p6",type:"review",user:US[2],time:"1d",bookRef:{title:"The Vegetarian",author:"Han Kang",cc:"#4A6A3A"},title:"Hunger as refusal",text:"Kang understands that the most terrifying act of autonomy isn't violence — it's silence.",rating:5,likes:78,comments:31,shelved:45,reposts:14,isLiked:false,isShelved:false,isReposted:false,tags:["international"],following:true}];
