// ─── CSS ─────────────────────────────────────────────────────
const gc=T=>`@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700&family=Source+Serif+4:ital,opsz,wght@0,8..60,300;0,8..60,400;0,8..60,500;1,8..60,400&family=Outfit:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}body{background:${T.bg}!important;overflow-x:hidden;-webkit-tap-highlight-color:transparent}::selection{background:${T.gold}30;color:${T.tx}}::-webkit-scrollbar{width:0;height:0}@keyframes en{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}@keyframes fi{from{opacity:0}to{opacity:1}}@keyframes si{from{opacity:0;transform:scale(.97)}to{opacity:1;transform:scale(1)}}@keyframes po{0%{transform:scale(1)}50%{transform:scale(1.25)}100%{transform:scale(1)}}.tb{-webkit-tap-highlight-color:transparent;touch-action:manipulation}.tb:active{opacity:.7;transform:scale(.97)}.cl{transition:border-color .2s,box-shadow .15s}@media(min-width:768px){.mh{display:none!important}.dh{display:flex!important}.bb{display:none!important}.fw{padding-bottom:0!important;max-width:680px;margin:0 auto}.fs{display:grid!important;grid-template-columns:1fr 300px;gap:24px;max-width:1020px;margin:0 auto;align-items:start}.sd{display:flex!important}.cl:hover{border-color:${T.bdrA};box-shadow:${T.sh};transform:translateY(-1px)}}@media(max-width:767px){.dh{display:none!important}.sd{display:none!important}.fs{display:block!important}}`;

// ─── PRIMITIVES ──────────────────────────────────────────────
function Av({T,i,ink=0,s=34}){const t=gT(ink);return <div style={{width:s,height:s,borderRadius:"50%",background:`linear-gradient(145deg,${t.c}20,${T.bg2})`,border:`1.5px solid ${t.c}28`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:T.ui,fontSize:s*.34,fontWeight:700,color:t.c,flexShrink:0}}>{i}</div>;}
function IB({T,ink,compact}){const t=gT(ink);return <span style={{display:"inline-flex",alignItems:"center",gap:3,padding:compact?"1px 5px":"2px 7px",borderRadius:4,fontSize:compact?9:10,fontWeight:600,fontFamily:T.ui,color:t.c,background:`${t.c}0D`}}>{compact?fN(ink):`${fN(ink)} · ${t.name}`}</span>;}
function LB({T,lens,compact}){const l=LN[lens];if(!l)return null;return <span style={{display:"inline-flex",alignItems:"center",gap:2,padding:"1px 6px",borderRadius:4,fontSize:9,fontWeight:500,fontFamily:T.ui,color:l.c,background:`${l.c}08`}}>{l.icon}{!compact&&` ${l.label}`}</span>;}
function TT({T,type}){const t=PT[type];if(!t)return null;const c=T[t.ck]||T.gold;return <span style={{display:"inline-flex",alignItems:"center",gap:3,padding:"2px 8px",borderRadius:4,fontSize:9,fontWeight:700,fontFamily:T.ui,color:c,background:`${c}0D`,letterSpacing:".04em",textTransform:"uppercase"}}>{t.icon} {t.label}</span>;}
function EB({T,icon,count,active,ac,onClick}){const[p,sP]=useState(false);return <button className="tb" onClick={()=>{onClick?.();sP(true);setTimeout(()=>sP(false),300);}} style={{display:"flex",alignItems:"center",gap:4,padding:"8px 10px",borderRadius:8,background:active?`${ac}0D`:"transparent",border:"none",cursor:"pointer",animation:p?"po .3s ease":"none",minHeight:40}}><span style={{fontSize:15,color:active?ac:T.tx4}}>{icon}</span><span style={{fontFamily:T.ui,fontSize:11,fontWeight:600,color:active?ac:T.tx4,fontVariantNumeric:"tabular-nums"}}>{fN(count)}</span></button>;}
function Sec({T,title,sub,children,action}){return <section style={{marginBottom:24}}><div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}><div><div style={{fontFamily:T.hd,fontSize:17,fontWeight:600,color:T.tx}}>{title}</div>{sub&&<div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic",marginTop:1}}>{sub}</div>}</div>{action}</div>{children}</section>;}
function Card({T,children,pad="16px",mb=0}){return <div className="cl" style={{background:T.sf,borderRadius:14,border:`1px solid ${T.bdr}`,padding:pad,marginBottom:mb}}>{children}</div>;}
function Empty({T,icon,title,sub}){return <div style={{textAlign:"center",padding:"48px 16px",animation:"fi .3s ease"}}><div style={{fontSize:36,marginBottom:10,opacity:.15}}>{icon}</div><div style={{fontFamily:T.hd,fontSize:18,fontWeight:600,color:T.tx,marginBottom:6}}>{title}</div><p style={{fontFamily:T.bd,fontSize:13,color:T.tx3}}>{sub}</p></div>;}

// ─── FEED CARD ───────────────────────────────────────────────
function FC({T,item,onToggle,index=0}){const[so,setSo]=useState(false);const[mo,setMo]=useState(false);
const content=<>{item.title&&<h3 style={{fontFamily:T.hd,fontSize:19,fontWeight:600,color:T.tx,lineHeight:1.3,marginBottom:6}}>{item.title}</h3>}<div style={{fontFamily:T.bd,fontSize:14.5,lineHeight:1.7,color:T.tx2,fontWeight:300,whiteSpace:"pre-line"}}>{item.text}</div></>;
return <article className="cl" style={{background:T.sf,borderRadius:14,border:`1px solid ${T.bdr}`,padding:"18px 16px 12px",animation:`en .35s ease ${index*.05}s both`}}>
<div style={{display:"flex",alignItems:"flex-start",gap:10,marginBottom:12}}><Av T={T} i={item.user.in} ink={item.user.ink} s={38}/><div style={{flex:1,minWidth:0}}><div style={{display:"flex",alignItems:"center",gap:5,flexWrap:"wrap"}}><span style={{fontFamily:T.ui,fontSize:13.5,fontWeight:650,color:T.tx}}>{item.user.name}</span>{item.attestation&&<span style={{fontSize:8,padding:"1px 5px",borderRadius:3,background:`${T.gn}0D`,color:T.gn,fontFamily:T.ui,fontWeight:700}}>✓ HUMAN</span>}{item.isFirst&&<span style={{fontSize:8,padding:"1px 5px",borderRadius:3,background:`${T.gold}0D`,color:T.gold,fontFamily:T.ui,fontWeight:700}}>✦ FIRST</span>}</div><div style={{display:"flex",alignItems:"center",gap:5,marginTop:2,flexWrap:"wrap"}}><span style={{fontFamily:T.ui,fontSize:11,color:T.tx4}}>{item.user.h}</span><span style={{color:T.tx4,fontSize:8}}>·</span><span style={{fontFamily:T.ui,fontSize:11,color:T.tx4}}>{item.time}</span><IB T={T} ink={item.user.ink} compact/><LB T={T} lens={item.user.lens} compact/></div></div><div style={{display:"flex",alignItems:"center",gap:6,flexShrink:0}}><TT T={T} type={item.type}/><div style={{position:"relative"}}><button className="tb" onClick={()=>setMo(!mo)} style={{background:"none",border:"none",cursor:"pointer",padding:8,fontSize:18,color:T.tx4,minWidth:36,minHeight:36,display:"flex",alignItems:"center",justifyContent:"center"}}>⋮</button>{mo&&<div onClick={()=>setMo(false)} style={{position:"absolute",top:"100%",right:0,background:T.sf,border:`1px solid ${T.bdrA}`,borderRadius:12,padding:6,minWidth:160,boxShadow:T.shL,zIndex:50,animation:"si .12s ease"}}>{["Hide post","Mute author","Report"].map(a=><button key={a} className="tb" style={{display:"block",width:"100%",padding:"12px 14px",borderRadius:8,border:"none",background:"none",fontFamily:T.ui,fontSize:13,color:a==="Report"?T.rd:T.tx2,cursor:"pointer",textAlign:"left",minHeight:44}}>{a}</button>)}</div>}</div></div></div>
{item.bookRef&&<div style={{display:"flex",alignItems:"center",gap:10,padding:"8px 12px",borderRadius:8,background:T.bg2,border:`1px solid ${T.bdr}`,marginBottom:10}}><div style={{width:26,height:38,borderRadius:3,flexShrink:0,background:`linear-gradient(140deg,${item.bookRef.cc||T.acc}90,${item.bookRef.cc||T.acc}50)`}}/><div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.tx}}>{item.bookRef.title}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3}}>{item.bookRef.author}</div></div>{item.rating&&<div style={{fontFamily:T.ui,fontSize:11,color:T.gold}}>{"★".repeat(item.rating)}<span style={{color:T.tx4}}>{"★".repeat(5-item.rating)}</span></div>}</div>}
{item.inspiredBy&&<div style={{display:"flex",alignItems:"center",gap:5,padding:"6px 10px",borderRadius:6,background:`${T.pl}06`,border:`1px solid ${T.pl}0D`,marginBottom:10,fontFamily:T.ui,fontSize:10.5,color:T.pl}}>◇ Inspired by <strong>{item.inspiredBy.title}</strong> — {item.inspiredBy.author}</div>}
{item.type==="spoiler"&&!so?<div style={{padding:"24px 16px",borderRadius:10,textAlign:"center",background:`repeating-linear-gradient(135deg,${T.rd}05,${T.rd}05 2px,transparent 2px,transparent 8px)`,border:`1px dashed ${T.rd}20`}}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.rd,letterSpacing:".08em",textTransform:"uppercase",marginBottom:4}}>⚠ Spoiler Zone</div><div style={{fontFamily:T.bd,fontSize:12,color:T.tx3,marginBottom:14}}>{item.bookRef?.title}{item.spoilerPage?` · ${item.spoilerPage}`:""}</div><button className="tb" onClick={()=>setSo(true)} style={{padding:"10px 24px",borderRadius:8,background:`${T.rd}0D`,border:`1px solid ${T.rd}20`,fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.rd,cursor:"pointer",minHeight:44}}>Reveal Content</button></div>:content}
{item.tags?.length>0&&<div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:10}}>{item.tags.map(t=><span key={t} style={{padding:"2px 8px",borderRadius:4,fontSize:10,fontFamily:T.ui,fontWeight:500,color:T.tx3,background:T.bg2,border:`1px solid ${T.bdr}`}}>{t}</span>)}</div>}
<div style={{display:"flex",alignItems:"center",gap:0,marginTop:12,paddingTop:10,borderTop:`1px solid ${T.bdr}`,marginLeft:-4,marginRight:-4}}><EB T={T} icon="♡" count={item.likes} active={item.isLiked} ac={T.rd} onClick={()=>onToggle(item.id,"like")}/><EB T={T} icon="↩" count={item.comments} active={false} ac={T.bl}/><EB T={T} icon="⊞" count={item.shelved} active={item.isShelved} ac={T.gold} onClick={()=>onToggle(item.id,"shelf")}/><EB T={T} icon="⤴" count={item.reposts} active={item.isReposted} ac={T.gn} onClick={()=>onToggle(item.id,"repost")}/><div style={{flex:1}}/><button className="tb" style={{background:"none",border:"none",cursor:"pointer",fontFamily:T.ui,fontSize:11,color:T.tx4,padding:"8px 6px",minHeight:40}}>⎘</button></div>
</article>;}

// ─── FEED SCREEN ─────────────────────────────────────────────
function FeedScreen({T,feed,onToggle,searchQ}){
const[filter,setFilter]=useState("foryou");const[pi,setPi]=useState(0);
const FL=[{id:"foryou",l:"✦ For You"},{id:"all",l:"All"},{id:"original",l:"✎ Original"},{id:"review",l:"◈ Reviews"},{id:"recommendation",l:"⬨ Recs"},{id:"spoiler",l:"⚠ Spoiler"}];
const filtered=filter==="foryou"?feed.filter(f=>f.following||f.lensMatch):filter==="all"?feed:feed.filter(f=>f.type===filter);
const searched=searchQ.trim()?filtered.filter(f=>{const q=searchQ.toLowerCase();return(f.title||"").toLowerCase().includes(q)||(f.text||"").toLowerCase().includes(q)||f.user.name.toLowerCase().includes(q)||(f.bookRef?.title||"").toLowerCase().includes(q);}):filtered;
return <>
<div style={{marginBottom:16}}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".1em",textTransform:"uppercase",marginBottom:8}}>Currently Reading</div><div style={{display:"flex",gap:8,overflowX:"auto",WebkitOverflowScrolling:"touch",scrollSnapType:"x mandatory",scrollbarWidth:"none"}}>{CR.map((cr,i)=><div key={i} className="tb" style={{flex:"0 0 auto",scrollSnapAlign:"start",display:"flex",alignItems:"center",gap:10,padding:"10px 14px",borderRadius:12,background:T.sf,border:`1px solid ${T.bdr}`,minWidth:180,maxWidth:220}}><Av T={T} i={cr.user.in} ink={cr.user.ink} s={28}/><div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:11.5,fontWeight:600,color:T.tx,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{cr.book}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx4}}>{cr.author}</div></div><div style={{width:30,height:30,borderRadius:"50%",flexShrink:0,background:`conic-gradient(${T.acc} ${cr.prog}%,${T.bdr} ${cr.prog}%)`,display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{width:24,height:24,borderRadius:"50%",background:T.sf,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:T.mn,fontSize:8,fontWeight:500,color:T.tx3}}>{cr.prog}</div></div></div>)}</div></div>
<div style={{display:"flex",gap:6,overflowX:"auto",WebkitOverflowScrolling:"touch",marginBottom:14,scrollbarWidth:"none"}}>{FL.map(f=><button key={f.id} className="tb" onClick={()=>setFilter(f.id)} style={{padding:"8px 16px",borderRadius:20,border:`1px solid ${filter===f.id?T.bdrA:T.bdr}`,fontFamily:T.ui,fontSize:12,fontWeight:filter===f.id?700:500,cursor:"pointer",whiteSpace:"nowrap",minHeight:38,background:filter===f.id?T.gs:"transparent",color:filter===f.id?T.gold:T.tx3}}>{f.l}</button>)}</div>
{searchQ&&<div style={{fontFamily:T.ui,fontSize:12,color:T.tx3,marginBottom:12}}>⌕ "{searchQ}" · {searched.length} found</div>}
<Card T={T} pad="16px 16px 14px" mb={14}><div style={{fontFamily:T.ui,fontSize:9,fontWeight:700,color:T.acc,letterSpacing:".1em",textTransform:"uppercase",marginBottom:8}}>✎ Writing Prompt</div><div style={{fontFamily:T.hd,fontSize:16,fontWeight:500,color:T.tx,lineHeight:1.45,fontStyle:"italic",marginBottom:12}}>"{PRM[pi]}"</div><div style={{display:"flex",gap:8}}><button className="tb" style={{flex:1,padding:"10px 0",borderRadius:8,border:"none",background:T.acc,color:"#fff",fontFamily:T.ui,fontSize:12,fontWeight:700,cursor:"pointer",minHeight:44,boxShadow:`0 2px 8px ${T.acc}30`}}>Write This</button><button className="tb" onClick={()=>setPi((pi+1)%PRM.length)} style={{padding:"10px 18px",borderRadius:8,border:`1px solid ${T.bdr}`,background:"none",color:T.tx3,fontFamily:T.ui,fontSize:12,fontWeight:600,cursor:"pointer",minHeight:44}}>Next</button></div></Card>
<div style={{display:"flex",flexDirection:"column",gap:10}}>{searched.length===0?<Empty T={T} icon="⌕" title={searchQ?`Nothing for "${searchQ}"`:"No posts here yet"} sub={searchQ?"Try different keywords.":"Be the first to write one."}/>:searched.map((item,i)=><FC key={item.id} T={T} item={item} onToggle={onToggle} index={i}/>)}</div>
<div style={{marginTop:16}}><Card T={T} pad="16px 16px 8px"><div style={{fontFamily:T.hd,fontSize:16,fontWeight:600,color:T.tx,marginBottom:12}}>Trending Now</div>{TRD.map((b,i)=><div key={i} className="tb" style={{display:"flex",alignItems:"center",gap:10,padding:"10px 4px",cursor:"pointer",borderBottom:i<TRD.length-1?`1px solid ${T.bdr}`:"none",minHeight:48}}><div style={{fontFamily:T.mn,fontSize:11,fontWeight:500,color:T.tx4,width:18,textAlign:"center"}}>{i+1}</div><div style={{width:22,height:32,borderRadius:3,flexShrink:0,background:`linear-gradient(140deg,${b.c}AA,${b.c}60)`}}/><div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.tx}}>{b.title}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3}}>{b.author}</div></div><span style={{fontFamily:T.mn,fontSize:10,fontWeight:500,color:T.gn,background:`${T.gn}0D`,padding:"2px 6px",borderRadius:3}}>{b.heat}</span></div>)}</Card></div>
{searched.length>0&&<div style={{textAlign:"center",padding:"40px 16px 24px",borderTop:`1px solid ${T.bdr}`,marginTop:16}}><div style={{fontFamily:T.hd,fontSize:20,fontWeight:600,color:T.tx,fontStyle:"italic",marginBottom:6}}>You're caught up.</div><p style={{fontFamily:T.bd,fontSize:13,color:T.tx3,lineHeight:1.6,maxWidth:340,margin:"0 auto 16px"}}>Everything new has been read. The page is yours.</p></div>}
</>;}

// ─── EXPLORE SCREEN ──────────────────────────────────────────
